function startRound(){if(horse.gallopOnly)return toast('Bolter is a fantasy free-ride horse. Choose another horse for tournaments.');if(player.skyMode||player.skyLaunching)return toast('Return to the ground before entering a tournament.');if(horse.noJump)return toast(horse.name+' cannot enter jumping classes. Enjoy flatwork together.');if(player.riderFallen)return toast('Recover and remount before entering.');if(!player.mounted||!player.tacked)return toast('Tack up and mount before entering.');if(round)return;const event=save.tournament||{level:'local',setting:'outdoor'};const cap=strideJumpProfile(horse).maxCm,courseTop=save.course.auto?Math.floor(cap/10)*10:save.course.heightCm;if(event.level==='international'&&courseTop<120)return toast('International tournaments require a class of at least 120 cm.');if(courseTop>cap)return toast('This tournament is above your horse’s jump limit. Choose a lower height.');closeModal();round={rivals:generateRivals(event.level,courseTop),level:event.level,setting:event.setting,next:0,faults:0,time:0,rail:0,refusals:0,wrong:0,heightCm:courseTop};configureCourse();resetPosition();fences.forEach(f=>{f.hit=false;f.cool=0;});round.heightCm=courseTop;$('enterBtn').hidden=true;$('roundHud').hidden=false;$('modeLabel').textContent=`${event.level.toUpperCase()} · ${event.setting.toUpperCase()} · ${cap<=60?'STARTER':cap<=80?'INTRO':cap<=100?'NOVICE':cap<=120?'CLUB':cap<=150?'ADVANCED':'BREEDER'} CLASS · ${Math.max(event.level==='international'?120:20,courseTop-20)}–${courseTop} CM`;$('eventTitle').textContent='Ride a clear round.';$('eventDesc').textContent=`${event.setting==='indoor'?'Indoor arena':'Outdoor stadium'} · first prize ${tournamentPrize(courseTop,1,event.level).toLocaleString()} coins · 180 seconds.`;toast('Round started. Canter to fence 1 and jump 3–4 m before it.');}
