let jumpStep=dt;if(player.jumpDelay>0){const consumed=Math.min(player.jumpDelay,dt);player.jumpDelay-=consumed;jumpStep-=consumed;if(player.jumpDelay<=1e-8){player.jumpDelay=0;if(player.speed>=2.6){player.jumpT=0;}else{player.jumpProfile=null;toast(`${horse.name} lost momentum before takeoff.`);}}}if(player.jumpT>=0){player.jumpT+=jumpStep;const attempt=player.jumpProfile||strideJumpAttempt(horse,player.speed,player.energy);player.y=(player.floorY||0)+strideJumpHeight(attempt,player.jumpT);if(player.skyLaunching&&player.jumpT>attempt.duration/2&&player.y<=skyArena.y){player.skyLaunching=false;player.skyMode=true;player.floorY=skyArena.y;player.y=skyArena.y;player.jumpT=-1;player.jumpProfile=null;player.speed=0;toast('Welcome to Tripod’s private sky arena!');}else if(player.jumpT>=attempt.duration){player.jumpT=-1;player.y=player.floorY||0;player.jumpProfile=null;}}player.energy=clamp(player.energy+dt*(player.speed>6?-1.8*(110-horse.stamina)/35:player.speed>3?-.2:3.5),0,100);
