for(const f of (horse.gallopOnly?[]:player.skyMode?skyFences:player.skyLaunching?[]:[...fences,practiceFence])){f.cool=Math.max(0,f.cool-dt);const prev=localFence(old.x,old.z,f),now=localFence(player.x,player.z,f);if(f.cool===0&&prev.v*now.v<=0&&Math.abs(prev.v-now.v)>.001){const fraction=Math.abs(prev.v)/(Math.abs(prev.v)+Math.abs(now.v)),crossU=lerp(prev.u,now.u,fraction),crossY=lerp(old.y,player.y,fraction)-(f.y||0);if(Math.abs(crossU)<3.1){f.cool=2;if(player.speed<2.7||player.jumpT<0){player.x=old.x;player.z=old.z;const wasPractice=f.id==='P',savedRound=round;if(wasPractice)round=null;refuseAtFence(player.jumpDelay>0?'Jump cue came too late':'No jump requested',f);if(wasPractice&&savedRound&&!player.riderFallen)round=savedRound;}else{const limit=(player.jumpProfile||strideJumpProfile(horse)).maxFenceHeight,overLimit=f.h>limit+.00001,rail=overLimit||crossY<f.h+.15;if(rail){f.hit=true;toast(overLimit?`${horse.name} can clear at most ${Math.round(limit*100)} cm — this fence is too high.`:'Rail down · adjust your takeoff to this horse’s arc.');if(!player.riderFallen&&seriousFenceMistake(player.speed,f.h,crossY,limit))riderFall('Major mistake: high-speed impact with a badly mistimed or far-too-high fence');}else{if(player.skyMode)f.cleared=true;cheerUntil=clock+2.5;toast(`Fence ${f.id} cleared — the crowd cheers!`);}if(round&&f.id!=='P'){if(f.id!==round.next+1){round.faults+=4;round.wrong++;toast(`Wrong fence · 4 faults. Ride fence ${round.next+1}.`);}else{if(rail){round.faults+=4;round.rail++;}round.next++;if(round.next===fences.length){finishRound();break;}}}}}}}
