function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function horseCard(h,action){return `<article class="card"><div class="tag">${escapeHTML(h.sex)} · ${h.age} YEARS${h.id==='juniper'?' · FREE STARTER':h.origin==='bred'?' · BRED · GEN '+h.generation:''}</div><h3>${escapeHTML(h.name)}</h3><div class="muted">${escapeHTML(h.breed)}</div><p>${h.age===0?'Projected style: ':''}${escapeHTML(strideJumpProfile(h).label)}</p><p class="muted">Behavior tendency: ${behaviorTraits(h).type} · ${h.temperament>=90?'usually calm':h.temperament>=65?'occasionally unsettled':'needs an experienced rider'}</p><div class="stats"><span>Speed <b>${h.speed}</b></span><span>Jump <b>${h.jump}</b></span><span>Stamina <b>${h.stamina}</b></span><span>Temperament <b>${h.temperament}</b></span><span>Max fence <b>${strideJumpProfile(h).maxCm} cm</b></span><span>Fresh arc <b>${strideJumpProfile(h).height.toFixed(2)} m</b></span><span>Airtime <b>${strideJumpProfile(h).duration.toFixed(2)} s</b></span></div>${action}</article>`;}
function loadSlot(id){if(round)return toast('Finish or withdraw your round before switching games.');if(!persist())return toast('Browser storage is unavailable. Your current game is kept open.');const slot=saveBank.slots.find(s=>s.id===id);if(!slot)return;saveBank.active=id;save={...defaultSave(),...cloneSave(slot.data)};horse=save.owned.find(h=>h.id===save.active)||save.owned[0];save.active=horse.id;leaveNetwork();keys.clear();Object.assign(player,{mounted:true,leading:false,leadSpeed:0,tacked:true,walker:null,energy:100,gait:3});resetPosition();configureCourse();persist();hud();renderMenu();toast('Loaded '+slot.name+'. Your other games are preserved.');}
function newSlot(name){if(round)return toast('Finish or withdraw your round before starting a new game.');if(!persist())return toast('Browser storage is unavailable. A new save cannot be stored safely.');const id='slot-'+Date.now()+'-'+Math.random().toString(36).slice(2,8),slot={id,name:String(name||'Game '+(saveBank.slots.length+1)).trim().slice(0,40)||'New game',updated:Date.now(),data:defaultSave()};saveBank.slots.push(slot);loadSlot(id);}
const incomeJobs={yard:{name:'Stable yard work',reward:600,goal:40,description:'Dismount in any stable yard and spend 40 seconds helping with the horses.'},flatwork:{name:'Flatwork demonstration',reward:1200,goal:60,description:'Ride for 60 seconds at walk, trot or canter. Works with Cometa too.'},trail:{name:'Field trail delivery',reward:1800,goal:3,description:'Ride to the west field, south meadow, then reception. Follow the waypoint hint.'}};
const trailPoints=[{x:-151,z:-13,name:'West field'},{x:-66,z:99,name:'South meadow'},{x:95,z:25,name:'Reception'}];
function jobHint(){const j=save.job;if(!j)return '';const info=incomeJobs[j.id];if(j.id==='trail'){const point=trailPoints[Math.min(2,j.progress||0)];return 'Trail delivery · '+point.name+' · '+Math.round(Math.hypot(player.x-point.x,player.z-point.z))+' m';}return info.name+' · '+Math.floor(j.progress||0)+' / '+info.goal+' seconds · '+info.reward+' coins';}
function updateIncome(dt){const j=save.job;if(!j||round||player.riderFallen||!incomeJobs[j.id])return;let changed=false;if(j.id==='yard'&&!player.mounted&&nearestBarn()){j.progress+=dt;changed=true;}if(j.id==='flatwork'&&player.mounted&&player.speed>1&&player.gait<=3){j.progress+=dt;changed=true;}if(j.id==='trail'&&player.mounted){const p=trailPoints[Math.min(2,j.progress)];if(Math.hypot(player.x-p.x,player.z-p.z)<8){j.progress++;changed=true;toast('Delivery checkpoint reached.');}}if(changed&&j.progress>=incomeJobs[j.id].goal){const info=incomeJobs[j.id];save.money+=info.reward;save.xp+=30;save.job=null;persist();toast(info.name+' complete · +'+info.reward.toLocaleString()+' coins!');}else if(changed&&clock-(j.lastSave||0)>5){j.lastSave=clock;persist();}}
function schoolCost(h){return Math.max(500,Math.round(strideTrainingCost(h)/10/100)*100);}
function saleValue(h){const base=h.origin==='bred'?(h.breedingCost||legacyBreedingCost(h))+(h.birthBonus||350):Math.round((h.price||2500)/2/100)*100;return Math.round(base+(h.trainingInvestment||0)+(h.trainedSessions||0)*350+Math.floor((h.riddenSeconds||0)/60)*100);}
function legacyBreedingCost(h){const parents=(h.parentIds||[]).map(id=>save.owned.find(p=>p.id===id)||market.find(p=>p.id===id));return parents.length===2&&parents.every(Boolean)?strideBreedingCost(...parents):strideBreedingCost(h,h);}
function saleHorses(){return [...save.owned,...save.foals.filter(f=>!f.sold&&!save.owned.some(h=>h.id===f.id))];}
function nearestBarn(){const at=player.mounted?player:player.walker||player;return strideVenue.barns.find(b=>Math.hypot(at.x-b.x,at.z-b.z)<20);}
function collectHorse(id){const b=nearestBarn(),chosen=save.owned.find(h=>h.id===id);if(save.walkerIds.includes(id))return toast('Stop this horse’s walker session before collecting it.');if(!b||!chosen)return toast('Walk to a barn or stable yard to collect your horse.');if(round)return toast('Withdraw before collecting another horse.');if(player.riderFallen)return toast('Recover before visiting the stable.');if(player.speed>.4)return toast('Halt before collecting a horse.');save.active=id;horse=chosen;Object.assign(player,{x:b.x,z:b.z+4,a:0,speed:0,y:0,jumpT:-1,jumpDelay:0,jumpProfile:null,mounted:false,leading:false,tacked:false,walker:{x:b.x+1,z:b.z+4,a:0,speed:0,phase:0}});jumpCooldown=0;persist();closeModal();hud();toast(horse.name+' collected. T to tack up, L to lead, E to mount.');}
async function networkPost(action,body){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);try{const response=await fetch(network.url+'/api/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:controller.signal});const data=await response.json();if(!response.ok)throw Error(data.error||'Connection failed');return data;}finally{clearTimeout(timeout);}}
function leaveNetwork(){const id=network.id;if(id)networkPost('leave',{id}).catch(()=>{});clearInterval(network.timer);network.timer=null;network.id=null;network.peers=[];network.status='Offline';}
async function syncNetwork(){if(!network.id||network.busy)return;network.busy=true;const id=network.id;try{const data=await networkPost('state',{id,state:{x:player.x,z:player.z,a:player.a,speed:player.mounted?player.speed:player.leadSpeed||0,gait:player.mounted?player.gait:1,energy:player.energy,y:player.y,jumpT:player.jumpT,phase:player.phase,size:horse.size||1,coat:horse.coat,riderFallen:player.riderFallen||!player.mounted,tacked:player.tacked}});if(network.id!==id)return;network.peers=data.peers;network.status='Connected · '+network.room+' · '+(data.peers.length+1)+' riders';}catch(e){if(network.id!==id)return;leaveNetwork();network.status='Disconnected: '+e.message;toast(network.status);}finally{network.busy=false;}}
function openModal(tab='stable'){if(tab==='saves')persist();keys.clear();player.speed=0;modalTab=tab;$('modal').hidden=false;$('tabs').hidden=false;renderMenu();$('closeModal').focus();}
